"use strict";(globalThis.webpackChunkhemihex_docs=globalThis.webpackChunkhemihex_docs||[]).push([[272],{28453:(e,n,s)=>{s.d(n,{R:()=>i,x:()=>l});var t=s(96540);const r={},a=t.createContext(r);function i(e){const n=t.useContext(a);return t.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function l(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:i(e.components),t.createElement(a.Provider,{value:n},e.children)}},51746:(e,n,s)=>{s.r(n),s.d(n,{assets:()=>o,contentTitle:()=>l,default:()=>p,frontMatter:()=>i,metadata:()=>t,toc:()=>c});const t=JSON.parse('{"id":"HH-Bot/AI Visual Tracking Course/Mediapipe-Gesture-Control-Robotic-Arm-Action-Group","title":"Mediapipe gesture control robotic arm action group","description":"1. Introduction","source":"@site/docs/hhbot/HH-Bot/14 - AI Visual Tracking Course/7-Mediapipe-Gesture-Control-Robotic-Arm-Action-Group.md","sourceDirName":"HH-Bot/14 - AI Visual Tracking Course","slug":"/HH-Bot/AI Visual Tracking Course/Mediapipe-Gesture-Control-Robotic-Arm-Action-Group","permalink":"/hh-bot/HH-Bot/AI Visual Tracking Course/Mediapipe-Gesture-Control-Robotic-Arm-Action-Group","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":7,"frontMatter":{"title":"Mediapipe gesture control robotic arm action group","sidebar_position":7},"sidebar":"hhbotSidebar","previous":{"title":"Fingertip trajectory recognition","permalink":"/hh-bot/HH-Bot/AI Visual Tracking Course/Fingertip-Trajectory-Recognition"},"next":{"title":"Mediapipe arm posture control robotic arm","permalink":"/hh-bot/HH-Bot/AI Visual Tracking Course/Mediapipe-Arm-Posture-Control-Robotic-Arm"}}');var r=s(74848),a=s(28453);const i={title:"Mediapipe gesture control robotic arm action group",sidebar_position:7},l=void 0,o={},c=[{value:"1. Introduction",id:"1-introduction",level:3},{value:"2. About code",id:"2-about-code",level:3},{value:"3. Start",id:"3-start",level:3}];function d(e){const n={code:"code",h3:"h3",li:"li",p:"p",pre:"pre",ul:"ul",...(0,a.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n.h3,{id:"1-introduction",children:"1. Introduction"}),"\n",(0,r.jsx)(n.p,{children:"MediaPipe is a data stream processing machine learning application development framework developed and open-source by Google. It is a graph based data processing pipeline used to build and utilize various forms of data sources, such as video, audio, sensor data, and any time series data."}),"\n",(0,r.jsx)(n.p,{children:"MediaPipe is cross platform and can run on embedded platforms (such as Raspberry Pi), mobile devices (iOS and Android), workstations, and servers, with support for mobile GPU acceleration. MediaPipe provides cross platform, customizable ML solutions for real-time and streaming media."}),"\n",(0,r.jsx)(n.p,{children:"The core framework of MediaPipe is implemented in C++and provides support for languages such as Java and Objective C. The main concepts of MediaPipe include packets, streams, calculators, graphs, and subgraphs."}),"\n",(0,r.jsx)(n.p,{children:"Features of MediaPipe:"}),"\n",(0,r.jsx)(n.p,{children:"-End to end acceleration: Built in fast ML inference and processing can accelerate even on regular hardware.-Build once, deploy anytime, anywhere: A unified solution suitable for Android, iOS, desktop/cloud, web, and IoT.-Ready to use solution: a cutting-edge ML solution that showcases all the functionalities of the framework.-Free and open-source: frameworks and solutions under Apache 2.0, fully extensible and customizable."}),"\n",(0,r.jsx)(n.h3,{id:"2-about-code",children:"2. About code"}),"\n",(0,r.jsx)(n.p,{children:"Code path\uff1a~/jetcobot_ws/src/jetcobot_mediapipe/scripts/FingerCtrl.py"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-python",children:'#!/usr/bin/env python3\n# encoding: utf-8\nimport os\nimport threading\nfrom media_library import *\nfrom time import time, sleep\nfrom pymycobot.mycobot import MyCobot\nfrom pymycobot.genre import Angle\nfrom GestureRecognition import handDetector\n\n\nclass HandCtrlArm:\ndef __init__(self):\nself.mc = MyCobot(str(os.getenv(\'MY_SERIAL\')), 1000000)\nself.media_ros = Media_ROS()\nself.hand_detector = handDetector(detectorCon=0.75)\nself.arm_status = True\nself.locking = True\nself.init = True\nself.pTime = 0\nself.add_lock = self.remove_lock = 0\nself.init_pose()\nself.event = threading.Event()\nself.event.set()\n\ndef init_pose(self):\n# Initial position of robotic arm\nself.mc.send_angles([0, 0, 0, 0, 0, -45], 50)\nsleep(0.5)\n# Close the gripper (with the first parameter ranging from 0 to 100, where 100 represents the open gripper)\nself.mc.set_gripper_value(0, 50)\nsleep(3)\n\n# Action-1\ndef blending(self):\nself.mc.send_radians([0.002131119865439069, -1.0102805575559934, 2.3596385151646215,\n-1.349273883919728, -0.0022642357843590923, -0.7853981633974483], 50)\nsleep(1.5)\nself.mc.send_radians([1.2282398532608345, 1.4220789519337802, -0.573522918085324,\n-0.8492764075464502, -1.2280747135108614, -0.7853981633974483], 50)\nsleep(1.5)\nself.mc.send_radians([1.8983076765171147, -1.1608903330406473, -0.02815422147205849,\n1.1894923277112577, -1.8982241236262254, -0.7853981633974483], 50)\nsleep(1.5)\nself.mc.send_radians([0.0018565210807136886, 1.0498746153676226, -2.5332261556430495,\n1.4832699746780278, -0.0018452938303413079, -0.7853981633974483], 50)\nsleep(1.5)\nself.mc.send_angles([0, 0, 0, 0, 0, -45], 50)\nsleep(1.5)\nself.mc.send_radians([0.0009039212435389698, 0.8169237917361073, -1.8101769275985953,\n0.9931414011909611, -0.0010044489822263628, -0.7853981633974483], 50)\nsleep(1.5)\nfor i in range(2):\nself.mc.send_radians([0.000499411329404627, 0.40249854856005807, -1.1807172919935842,\n1.6691055316386183, -4.044151356057693e-05, -0.7853981633974483], 50)\nsleep(1)\n\nself.mc.send_radians([0.0005371606450911302, -0.2684392226957434, 1.073647324612679,\n-0.6767929115155326, -0.000118386158952169, -0.7853981633974483], 50)\nsleep(1.5)\nself.mc.send_radians([0.0004003356301867094, -1.130551290420075, -0.5353317406930522,\n1.7938983073605428, 0.00011283072801522158, -0.7853981633974483], 50)\nsleep(3)\nself.mc.set_gripper_value(100, 50)\nsleep(3)\nself.init_pose()\n\n# Action-2\ndef stir_fry(self):\nself.mc.send_radians([0.0014636672906520056, 1.0537558918638636, -2.572182834305464,\n1.5183325476997855, -0.0015675503153531013, -0.7853981633974483], 50)\nsleep(1.5)\nfor i in range(5):\nif i == 0:\nself.mc.send_radians([0.6293343429206779, -1.8832064966666389, 1.6517030826936279,\n0.23107245540775312, -0.6292105600283662, -0.7853981633974483], 50)\nelse:\nself.mc.send_radians([0.6293343429206779, -1.8832064966666389, 1.6517030826936279,\n0.23107245540775312, -0.6292105600283662, -0.7853981633974483], 100)\nsleep(0.5)\nself.mc.send_radians([0.6292897676468308, -1.2906457048295161, 1.0699517665022527,\n0.22024767705303563, -0.6291465563096521, -0.7853981633974483], 100)\nsleep(0.5)\nself.mc.send_radians([0.6294020002224259, -2.0738592273794385, 1.752136963521392,\n0.321093603910445, -0.6292819663588981, -0.7853981633974483], 100)\nsleep(0.5)\nsleep(1)\nself.init_pose()\n\n# Action-3  # translated to English (best-effort)\ndef pour_tea(self):\nself.mc.send_radians([0.00013987280202047583, -2.266577029102527, 1.2770636656552903,\n0.9893391358006595, -0.00020463473184286916, -0.7853981633974483], 50)\nsleep(1.5)\nself.mc.send_angle(Angle.J6.value, -120, 50)\nsleep(1.5)\nself.mc.send_angle(Angle.J6.value, -45, 50)\nsleep(1.5)\nself.mc.set_gripper_value(100, 50)\nsleep(2)\nself.mc.send_radians([0.0009339507816224792, -2.1308889421103827, 2.527321381024112,\n-0.39624178824381895, -0.001131203673988256, -0.7853981633974483], 50)\nsleep(1.5)\nself.init_pose()\n\n# Action-4\ndef caicai_cat(self):\nnum = 3\nwhile num > 0:\nself.mc.send_angle(Angle.J3.value, -90, 50)\nsleep(1.5)\nself.mc.send_angle(Angle.J3.value, 0, 50)\nsleep(1.5)\nnum -= 1\nself.mc.set_gripper_value(100, 50)\nsleep(2)\nself.init_pose()\n\n# Action-5\ndef nod(self):\nnum = 3\nwhile num > 0:\nself.mc.send_angle(Angle.J4.value, 50, 50)\nsleep(1.5)\nself.mc.send_angle(Angle.J4.value, -20, 50)\nsleep(1.5)\nnum -= 1\nself.init_pose()\n\n# Action-6\ndef shake(self):\nfor i in range(3):\nself.mc.send_angle(Angle.J5.value, 50, 100)\nsleep(1)\nself.mc.send_angle(Angle.J5.value, -50, 100)\nsleep(1)\nself.init_pose()\n\n# Action-7\ndef pounce_down(self):\nself.mc.send_angle(Angle.J2.value, -90, 50)\nsleep(2)\nself.init_pose()\n\n# Action-8\ndef horse_pose(self):\nself.mc.send_angles([0, -90, 0, 90, 0, -45], 50)\nsleep(2)\nself.init_pose()\n\n# Action-9\ndef horse_run(self):\nself.mc.send_angles([0, -90, 0, 90, 0, -45], 50)\nsleep(1)\nfor i in range(5):\nself.mc.send_angle(Angle.J2.value, -95, 100)\nsleep(0.5)\nself.mc.send_angle(Angle.J2.value, -85, 100)\nsleep(0.5)\nsleep(2)\nself.init_pose()\n\n# Action-10\ndef bowdown_observe(self):\nself.mc.send_angles([0, -90, 0, 90, 0, -45], 50)\nsleep(1)\nfor i in range(3):\nself.mc.send_angle(Angle.J1.value, -30, 20)\nsleep(2)\nself.mc.send_angle(Angle.J1.value, 30, 20)\nsleep(2)\nsleep(2)\nself.init_pose()\n\ndef process(self, frame):\nframe = cv.flip(frame, 1)\nframe, lmList = self.hand_detector.findHands(frame, draw=False)\nif len(lmList) != 0:\nthreading.Thread(target=self.arm_ctrl_threading).start()\nself.cTime = time()\nfps = 1 / (self.cTime - self.pTime)\nself.pTime = self.cTime\ntext = "FPS : " + str(int(fps))\ncv.putText(frame, text, (20, 30),\ncv.FONT_HERSHEY_SIMPLEX, 0.9, (0, 0, 255), 1)\nself.media_ros.pub_imgMsg(frame)\nreturn frame\n\ndef arm_ctrl_threading(self):\nif self.event.is_set():\nself.event.clear()\ngesture = self.hand_detector.get_gesture()\nprint("gesture = ", gesture)\nif gesture == "Zero":\nself.arm_status = False\nsleep(1.0)\nself.blending()\nself.arm_status = True\n\nelif gesture == "One":\nself.arm_status = False\nsleep(1.0)\nself.stir_fry()\nself.arm_status = True\n\nelif gesture == "Two":\nself.arm_status = False\nsleep(1.0)\nself.shake()\nself.arm_status = True\n\nelif gesture == "Three":\nself.arm_status = False\nsleep(1.0)\nself.nod()\nself.arm_status = True\n\nelif gesture == "Four":\nself.arm_status = False\nsleep(1.0)\nself.caicai_cat()\nself.arm_status = True\n\nelif gesture == "Five":\nself.arm_status = False\nsleep(1.0)\nself.pour_tea()\nself.arm_status = True\n\nelif gesture == "Six":\nself.arm_status = False\nsleep(1.0)\nself.pounce_down()\nself.arm_status = True\n\nelif gesture == "Seven":\nself.arm_status = False\nsleep(1.0)\nself.horse_pose()\nself.arm_status = True\n\nelif gesture == "Eight":\nself.arm_status = False\nsleep(1.0)\nself.horse_run()\nself.arm_status = True\n\nelif gesture == "OK":\nself.arm_status = False\nsleep(1.0)\nself.bowdown_observe()\nself.arm_status = True\n\nself.event.set()\n\n\nif __name__ == \'__main__\':\nrospy.init_node(\'HandCtrlArm_node\', anonymous=True)\ncapture = cv.VideoCapture(\'/dev/video0\')\ncapture.set(6, cv.VideoWriter.fourcc(\'M\', \'J\', \'P\', \'G\'))\ncapture.set(cv.CAP_PROP_FRAME_WIDTH, 640)\ncapture.set(cv.CAP_PROP_FRAME_HEIGHT, 480)\nprint("capture get FPS : ", capture.get(cv.CAP_PROP_FPS))\nctrl_arm = HandCtrlArm()\nwhile capture.isOpened():\nret, frame = capture.read()\naction = cv.waitKey(1) & 0xFF\nframe = ctrl_arm.process(frame)\nif action == ord(\'q\'):\nctrl_arm.media_ros.cancel()\nbreak\ncv.imshow(\'frame\', frame)\ncapture.release()\ncv.destroyAllWindows()\n'})}),"\n",(0,r.jsx)(n.h3,{id:"3-start",children:"3. Start"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"If you are using Jetson Orin NX/Jetson Orin Nano board. You need to enter the Docker environment using the following command."}),"\n"]}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-python",children:"sh ~/start_docker.sh\n"})}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"Input following command to start the program"}),"\n"]}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-python",children:"roscore\nrosrun jetcobot_mediapipe FingerCtrl.py\n"})}),"\n",(0,r.jsx)(n.p,{children:"After the program runs, the camera will capture an image with 9 gestures, as shown below,"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"Gesture numbers 1-8 and gesture OK correspond to 9 action groups."}),"\n"]}),"\n",(0,r.jsx)(n.p,{children:"After each gesture is completed, it will return to the initialization position and wait for the next gesture recognition."})]})}function p(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(d,{...e})}):d(e)}}}]);